<template>
 <el-dialog title="核对合包归属" :visible.sync="visible" width="min(1100px,96vw)" append-to-body :close-on-click-modal="false">
  <div v-loading="loading" style="max-height:65vh;overflow-y:auto;padding-right:12px" v-if="record">
   <el-alert :title="record.issue.reason" description="目标包裹的实收不等于本退款已收到商品。请先核实实物归属；本页不会自动分配实收或增加库存。" type="warning" show-icon :closable="false"/>
   <div class="scope"><b>本退款：{{ refund.refund_sn }}</b><p>计划退回 {{ record.plan.quantity }} 件 · 已确认实收 {{ record.plan.accepted_quantity }} 件 · 已入账 {{ record.plan.posted_quantity }} 件</p><p>{{ record.plan.has_document?'已有仓库单，请核对原单':'尚未加入目标包裹共同THK' }}</p></div>
   <template v-if="target.id"><h4>目标包裹 · 只读核对</h4><p>{{ target.carrier_code }} · {{ target.waybill }}<br><span class="hint">{{ target.parcel_sn }} · 退回仓 {{ target.store_code }} · 货主 {{ target.owner_code }}</span></p>
    <div class="scope">已关联 {{ refundCount }} 笔退款 · 仓库报告 {{ reported }} 件 · 已确认实收 {{ total('accepted_quantity') }} 件 · 已入账 {{ total('posted_quantity') }} 件 · 待分配 {{ waiting }} 件<p class="hint">这些是目标包裹的数量，尚不能认定其中任何数量属于本退款。</p></div>
    <el-collapse><el-collapse-item title="查看已关联退款与仓库回传明细" name="facts"><el-alert v-if="target.receipt_limit_reached" title="回传较多，数量为当前展示记录合计；完整记录请查仓库交互日志。" type="info" :closable="false"/><el-table :data="target.members" size="small"><el-table-column prop="refund_sn" label="已关联退款" min-width="250"/><el-table-column label="原退回单 / SKU" min-width="280"><template slot-scope="s">{{ s.row.return_sn||'待生成' }}<div class="hint">{{ s.row.sku_sn }}</div></template></el-table-column><el-table-column label="计划 / 实收 / 入账" min-width="150"><template slot-scope="s">{{ s.row.quantity }} / {{ s.row.accepted_quantity||0 }} / {{ s.row.posted_quantity||0 }}</template></el-table-column></el-table>
    <el-table :data="target.receipts" size="small" empty-text="暂无回传"><el-table-column prop="message_id" label="仓库回传消息" min-width="220"/><el-table-column prop="quantity" label="数量" width="80"/><el-table-column label="归属处理" min-width="240"><template slot-scope="s">{{ ({WAIT_ALLOCATION:'待人工分配，尚未入账',ALLOCATED:'已分配，按退款来源核对入账',DOCUMENT:'已按具体THK处理',REJECTED:'已拒绝本次回传'})[s.row.state] }}</template></el-table-column></el-table>
    <p><router-link :to="{path:'/oms-supplychain/wmsLogs',query:{numberType:'DOCUMENT',number:target.parcel_sn,allTime:'true'}}">查看目标包裹仓库交互日志</router-link></p></el-collapse-item></el-collapse>
   </template>
   <h4>选择核实结果与下一步</h4><el-radio-group v-model="form.decision" class="decisions"><el-radio label="CORRECT_LOGISTICS">实际是另一个包裹 → 更正寄回物流</el-radio><el-radio label="WAIT_BUYER">商品尚未寄回 → 等待买家提供真实物流</el-radio><el-radio label="WAREHOUSE_CHECK">确在原包裹或暂不能确认归属 → 转仓库差异核对</el-radio><el-radio label="NOT_RETRIEVED">确定不再追回 → 转剩余不再追回／差异处理</el-radio></el-radio-group>

   <el-alert v-if="form.decision==='WAIT_BUYER'" title="暂停使用当前平台运单自动关联" description="记录后等待本退款真实寄回物流；原平台来源保留，不会自动加入原包裹。" type="info" :closable="false"/>
   <el-alert v-if="form.decision==='WAREHOUSE_CHECK'" title="记录待仓库核对事项，保持阻断" description="此操作不会向仓库发送指令。核对共同THK原预报范围与实物；本期不通过新增THK扩大原包裹计划。" type="info" :closable="false"/>
   <el-alert v-if="form.decision==='NOT_RETRIEVED'" title="下一步填写终止追回的数量与凭证" description="将进入现有差异处理流程，需单独确认；不会直接标记收货、增加库存或执行平台退款。" type="info" :closable="false"/>
   <el-form v-if="form.decision&&form.decision!=='NOT_RETRIEVED'" label-width="120px" style="margin-top:18px"><template v-if="form.decision==='CORRECT_LOGISTICS'"><el-form-item label="核实的快递编码" required><el-input v-model.trim="form.carrier_code" maxlength="50" placeholder="例如 SF"/></el-form-item><el-form-item label="核实的退回运单" required><el-input v-model.trim="form.waybill" maxlength="50"/></el-form-item></template><el-form-item label="核对依据" required><el-input v-model.trim="form.reason" type="textarea" maxlength="500"/></el-form-item><el-form-item label="仓库／买家凭证" required><el-input v-model.trim="form.evidence" type="textarea" maxlength="1000"/></el-form-item><el-form-item><el-checkbox v-model="form.confirmed">已核实本退款实物、数量、包裹归属及下一步处理</el-checkbox></el-form-item></el-form>
  </div><span slot="footer"><div v-if="form.decision" class="footer-guide">{{ submitHint }}<el-button v-if="form.decision==='SAME_PARCEL'&&!target.late_append_supported" type="text" @click="form.decision='WAREHOUSE_CHECK'">转仓库差异核对</el-button></div><el-button @click="visible=false">返回</el-button><el-button type="primary" :loading="saving" :disabled="!canSubmit" @click="submit">{{ submitLabel }}</el-button></span>
 </el-dialog>
</template>
<script>
import {refundParcelReviewContext,reviewRefundParcel} from '@/api/order/refund'
export default {name:'RefundParcelIssueReview',props:{refund:{type:Object,required:true}},data:()=>({visible:false,loading:false,saving:false,record:null,plan:0,form:{},sequence:0}),computed:{submitHint(){if(this.form.decision==='SAME_PARCEL')return this.target.late_append_supported?'下一步：填写核对依据与凭证并勾选实物确认；提交只补充关联，不增加库存。':'当前不能补充关联：仓库尚未确认收货后补单能力。请先核实能力，或转仓库差异核对。';return ({CORRECT_LOGISTICS:'下一步：填写核实的新承运商、运单、依据和凭证，再确认提交。',WAIT_BUYER:'记录等待寄回后，将暂停使用旧运单自动关联。',WAREHOUSE_CHECK:'填写仓库待核对事项和依据；保存后保持阻断，取得凭证后继续核对。',NOT_RETRIEVED:'下一步进入差异处理，单独确认未追回数量与凭证；本页不直接结案。'})[this.form.decision]||''},target(){return this.record&&this.record.target||{}},refundCount(){return new Set((this.target.members||[]).map(m=>m.refund_id)).size},reported(){return (this.target.receipts||[]).filter(r=>r.state!=='REJECTED').reduce((n,r)=>n+Number(r.quantity),0)},waiting(){return (this.target.receipts||[]).filter(r=>r.state==='WAIT_ALLOCATION').reduce((n,r)=>n+Number(r.quantity),0)},submitLabel(){return ({SAME_PARCEL:'确认补充关联',CORRECT_LOGISTICS:'保存更正并重新检查',WAIT_BUYER:'记录等待寄回',WAREHOUSE_CHECK:'记录待仓库核对',NOT_RETRIEVED:'进入差异处理'})[this.form.decision]||'请选择核实结果'},canSubmit(){if(!this.record||!this.form.decision||this.loading)return false;if(this.form.decision==='NOT_RETRIEVED')return true;if(!this.form.confirmed||!this.form.reason||!this.form.evidence)return false;if(this.form.decision==='SAME_PARCEL')return !!this.target.late_append_supported&&this.form.buyer_verified&&this.form.warehouse_verified;if(this.form.decision==='CORRECT_LOGISTICS')return !!this.form.carrier_code&&!!this.form.waybill;return true}},methods:{total(k){return (this.target.members||[]).reduce((n,m)=>n+Number(m[k]||0),0)},async open(plan){const seq=++this.sequence;this.plan=Number(plan);this.record=null;this.form={decision:'',reason:'',evidence:'',confirmed:false,buyer_verified:false,warehouse_verified:false,carrier_code:'',waybill:''};this.visible=true;this.loading=true;try{const r=(await refundParcelReviewContext(this.refund.id,this.plan)).data;if(seq===this.sequence)this.record=r}finally{if(seq===this.sequence)this.loading=false}},async submit(){if(!this.canSubmit||this.saving)return;if(this.form.decision==='NOT_RETRIEVED'){this.visible=false;this.$emit('waive',this.plan);return}this.saving=true;try{await reviewRefundParcel(this.refund.id,this.plan,{...this.form,control_version:this.record.control_version,plan_version:this.record.plan.version,parcel_version:this.target.control_version});this.visible=false;this.$message.success(this.form.decision==='SAME_PARCEL'?'已补充关联；下一步人工下发本退款THK，再核对实收归属。库存未增加。':'核对结论已保存，请按页面下一步继续处理');this.$emit('changed')}finally{this.saving=false}}}}
</script>
<style scoped>.footer-guide{text-align:left;background:#fff7e8;color:#94620f;padding:10px 14px;margin-bottom:12px;line-height:1.7;border-radius:6px}.scope{padding:10px 14px;background:#f4f7fc;border-radius:6px;margin:10px 0;line-height:1.6}.scope p{margin:5px 0}.hint{color:#8290a4;font-size:12px}.decisions{display:flex;flex-direction:column;gap:10px;margin:14px 0}.decisions .el-radio{white-space:normal;line-height:1.7}.el-alert{margin:14px 0}a{color:#1677ff}</style>
